questionvariables.text:
/* --- 1. SCENARIOS (described actions -> method) --- */
/* Methods restricted to those taught in the lesson:                       */
/* Observation, Interview, Questionnaire, Experimentation, Secondary Data. */
scenarios: [
  ["A wildlife ranger hides in a blind to count the elephants visiting a watering hole at sunset, without disturbing them.", "Observation"],
  ["A researcher sits down one-on-one with each shopkeeper in a market and asks them detailed questions about their daily challenges, recording each conversation.", "Interview"],
  ["A university sends a standard form by email to all 10,000 students, asking them to rate the cafeteria food on a scale of 1 to 5.", "Questionnaire"],
  ["A farmer applies a new fertilizer to Plot A and the old fertilizer to Plot B, keeping everything else the same, to see which produces more maize.", "Experimentation"],
  ["An economist analyses Kenya's inflation rates from 1990 to 2020 using annual reports already published by the National Bureau of Statistics.", "Secondary Data Collection"]
];

/* Pick a random scenario */
rand_idx: rand(length(scenarios)) + 1;
chosen_scenario: scenarios[rand_idx];
q_text: chosen_scenario[1];
correct_text: chosen_scenario[2];

/* --- 2. OPTIONS: correct + 3 distinct distractors from taught methods --- */
all_methods: ["Observation", "Interview", "Questionnaire", "Experimentation", "Secondary Data Collection"];
wrong_pool: sublist(all_methods, lambda([x], x # correct_text));
chosen_wrongs: rand_selection(wrong_pool, 3);

correct_answer: [[1, true, correct_text]];
incorrect_answers: [
   [2, false, chosen_wrongs[1]],
   [3, false, chosen_wrongs[2]],
   [4, false, chosen_wrongs[3]]
];
ta: random_permutation(append(correct_answer, incorrect_answers));

/* Helper for question testing: a wrong option's value */
wrongval(t) := first(delete(1, map(first, t)));
